        "rawText": "【引言：時鐘的祕密】\n各位小朋友，你們家裡有時鐘嗎？滴答、滴答，時間總是不停地走。有時候你覺得時間過得很慢（像是快要放學前），有時候又覺得過得很快（像是玩電動時）。很久以前，有一位很有智慧的國王叫作所羅門，他發現了一個祕密：這世界上發生的每一件事，都有一個「正確的時間」。",
        "teacherScript": "『孩子們，讓我們把時光倒流！看著這幅圖畫，主角正在面臨前所未有的考驗……想像如果是你，你會怎麼辦？』",
