        "rawText": "所羅門王觀察這世界。他看到農民在春天撒種，秋天收割；他看到小嬰兒出生，也看到老人家安息。他說：「生有時，死有時；栽種有時，拔出也有時。」\n他發現，如果我們在冬天想要採收蘋果，那是採不到的；如果我們還沒翻土就想撒種，種子也長不出來。這就是「定時」。上帝在創造世界的時候，就為每一件事設定了鬧鐘。",
        "teacherScript": "『請大家注意看這個重點：【【萬事都有定時】】。這段話告訴我們上帝對我們每個人的美好心意！』",
