        "rawText": "人生就像一場精彩的冒險，有上坡的辛苦，也有下坡的暢快。請記住，你的每一天、每一秒，都不是隨機發生的，而是上帝這位偉大的創造者，正精心地為你調配色彩。當你覺得孤單、不明白為什麼某件事情的發生時，請回想這段經文。\n我們雖然不能參透上帝整幅畫作的全貌，但我們可以牽著祂的手，信任祂的預備與慈愛。因為在上帝手中，沒有任何一段時光是浪費的。祂承諾，萬物必將在適當的時刻，於跟隨祂的人的生命中綻放出最美好的樣貌。",
        "teacherScript": "『請大家注意看這個重點：【結語】。這段話告訴我們上帝對我們每個人的美好心意！』",
