        "timing": "⏱️ 建議停留：2-3 分鐘",
        "rawText": "（傳道書4-12章）\n背誦金句：「敬畏上帝，謹守他的誡命，這是人所當盡的本分。」（傳道書12章13節下）\n信息經文：傳道書四至十二章\n主題經文：傳道書11章9節～12章1、13-14節\n少年人哪，你在幼年時當快樂。在幼年的日子，使你的心歡暢，行你心所願行的，看你眼所愛看的；卻要知道，為這一切的事，上帝必審問你。所以你當從心中除掉愁煩，從肉體克去邪惡；因為一生的開頭和幼年之時，都是虛空的。\n你趁著年幼、衰敗的日子尚未來到，就是你所說，我毫無喜樂的那些年日未曾臨近之先，當紀念造你的主。\n這些事都已聽見了，總意就是：敬畏上帝，謹守他的誡命，這是人所當盡的本分（或譯：這是眾人的本分）。因為人所做的事，連一切隱藏的事，無論是善是惡，上帝都必審問。",
        "teacherScript": "『小朋友早！今天我們要一起進入第4課【智慧國王的祕密】！請大家看看這張美麗的投影片，上帝今天為我們準備了一個超級逆轉的恩典大冒險！』",
        "studentPrompt": "大家今天出門時心情怎麼樣？有沒有準備好尋找今天的聖經寶藏？"
