        "rawText": "但隔天，上帝叫一條蟲咬死蓖麻樹，樹枯萎了，約拿被曬得快要昏倒，氣得說：「讓我死了算了！」\n上帝的回應\n上帝對約拿說：「這棵樹你沒種過、也沒養過，它枯了你都這麼心疼；更何況這尼尼微城裡，還有十二萬多個不懂事的小朋友，還有這麼多動物，我難道不應該愛惜他們嗎？」\n約拿這才明白，上帝的愛是多麼寬廣。祂不只愛以色列人，也愛世上每一個願意轉向祂的人，哪怕是我們最不喜歡的人。",
        "teacherScript": "『請大家注意看這個重點：【蓖麻樹枯萎】。這段話告訴我們上帝對我們每個人的美好心意！』",
        "studentPrompt": "誰能用自己的話，把這句話解釋給隔壁的同學聽？"
