        "timing": "⏱️ 建議停留：3-4 分鐘",
        "rawText": "順服勝於逃避\n面對上帝的呼召，逃避會遇風浪，唯有順服\n才能帶來平安與祝福。\n悔改必蒙赦免\n不管過去多壞，只要真心認錯離開惡行，\n上帝永遠願意給我們機會。\n神愛世上萬民\n每個生命在上帝眼中都很寶貴，我們不應因偏見\n而限制上帝的慈愛。\n體貼神的心腸\n學習放下自己的舒適與情緒，用上帝寬廣的眼光去\n看待每個靈魂。",
        "teacherScript": "『孩子們，讓我們把時光倒流！看著這幅圖畫，主角正在面臨前所未有的考驗……想像如果是你，你會怎麼辦？』",
        "studentPrompt": "如果是你站在他的位置，你的手心會不會冒汗？你覺得上帝在暗中做什麼事？"
