        "timing": "⏱️ 建議停留：8-10 分鐘",
        "rawText": "透過清理障礙，體會「依靠上帝，大山成為平地」的應許。\n準備材料\n大量報紙或廢紙\n彩色膠帶（作中線）\n計時器、背景音樂\n操作步驟\n製作障礙：將紙揉成球，代表困難（如害怕、吵架）。\n劃分場地：以膠帶分隔空間，將紙球平均分配至兩側。\n限時對抗：60秒內，兩隊需將自己區域的紙球推至對方場地。\n大山移開：最後10秒宣告：「依靠上帝，大山變平地！」加快清理。\n總結：紙球少者獲勝。強調靠主能挪去所有困難。",
        "teacherScript": "『大家準備好了嗎？我們現在要進行超好玩的破冰遊戲【遊戲一：大山變平地】！遊戲的規則非常簡單，請大家豎起耳朵聽清楚囉！』",
        "studentPrompt": "在遊戲中請注意安全，輸贏不重要，最重要的是彼此相愛互相加油！"
