        "rawText": "在一個陽光普照的主日，老使徒約翰獨自一人在拔摩海島上。雖然他因為信仰而被放逐，但心裡卻仍然充滿著對上帝的敬拜。突然，他聽到身後有一個如同吹號般的巨大聲音！約翰嚇了一跳，趕緊轉過身來，他看見了一幅他這輩子從未見過的景象。\n他看見了七個閃閃發光的金燈臺，而在燈臺的中間，站著一位讓他既熟悉又感到震撼的神聖人物。那是一位「好像人子」的……沒錯！就是他最愛的耶穌！",
