        "rawText": "材料\n鈴鐺或響板。\n步驟\n學生分為四活物組、長老組、天使組、受造物組。\n老師讀經文，讀到哪一組，該組就要立刻站起來大聲說「阿們」或「頌讚歸給主」並搖動樂器。\n四活物組\n說「阿們！」\n長老組\n俯伏敬拜\n天使組\n千千萬萬歡呼\n受造物組\n頌讚歸給主",
