        "timing": "⏱️ 建議停留：3-4 分鐘",
        "rawText": "小朋友們，你們有沒有遇過一種情況，是很想打開一個東西，卻怎麼也打不開？可能是打不開的罐子，或者是忘記密碼的平板電腦？今天的故事，要帶我們去一個最神奇的地方，看一個全宇宙最難打開的東西。\n還記得上一課，主耶穌給老約翰的使命嗎？老約翰不單看見了人子與金燈臺，上帝還讓他看到奇妙的異象。\n他看見天打開了，上帝坐在榮耀的寶座上。最特別的是，在上帝的手中有一卷書卷，這卷書很特別，外面被七個蠟印封得死死的。",
