        "rawText": "這卷書裡面寫著上帝要怎樣拯救這個世界，怎樣讓痛苦消失、讓正義來到。\n這時候，有一位力量很大的天使出現了，他大聲喊著說：「有誰配得開啟那書卷，揭開那七個印呢？」\n約翰等啊等，看啊看。他在天上找，找不到；在地上找，找不到；連在地底下找，也沒有人可以。這世界上最聰明的人、最強壯的國王、最厲害的英雄，沒有一個人「夠資格」去拿那卷書，更別說打開它了。\n約翰看到這裡，心裡好難過，他竟然大哭了起來。\n因為如果沒有人能打開書卷，就表示上帝的救贖計畫不能完成，世界就沒有希望了。",
