        "timing": "⏱️ 建議停留：2-3 分鐘",
        "rawText": "就在約翰哭得很傷心的時候，一位長老走過來，拍拍他的肩膀說：「約翰，不要哭！你看！猶大支派中的獅子，大衛的根，祂已經得勝了！祂可以打開那書卷，揭開那七個印。」\n約翰趕快擦乾眼淚，心想：「哇！是獅子耶！一定非常威武吧！」結果，當他轉過頭去，他看到的不是一隻威風凜凜、張牙舞爪的大獅子，而是一隻「羔羊」。更奇怪的是，這隻羔羊看起來像是「曾經被殺過的」。\n🦁 獅子\n耶穌像獅子一樣勇敢、有權柄\n🐑 羔羊\n耶穌也像羔羊一樣，為了救我們，甘心在十字架上犧牲了自己。\n這隻羔羊就是主耶穌。祂為什麼是獅子又是羔羊呢？因為耶穌像獅子一樣勇敢、有權柄，但祂也像羔羊一樣，為了救我們，甘心在十字架上犧牲了自己。",
        "teacherScript": "『請大家注意看這個重點：【獅子？還是羔羊？】。這段話告訴我們上帝對我們每個人的美好心意！』",
