        "timing": "⏱️ 建議停留：2-3 分鐘",
        "rawText": "這時候，約翰聽到天上有聲音對他說：「去，把天使手裡展開的小書卷拿過來。」約翰走過去，天使看著他，給了他一個奇怪的指令：「拿著，把它吃下去！」\n小朋友，你有吃過書嗎？這聽起來很不可思議。約翰聽從話語把書卷吃了。沒想到，當書卷在嘴巴裡的時候，哇！感覺像蜂蜜一樣甜滋滋的，那種感覺就像你讀到「上帝愛你」、「耶穌會永遠陪著你」一樣，心裡好溫暖、好幸福。\n但是，當約翰把書卷吞進肚子裡後，肚子竟然覺得發苦。為什麼會先甜後苦呢？因為上帝的話語雖然充滿了愛，但也交給我們一份很不容易的任務。\n上帝告訴約翰：「你必須再去對許多民族、國家、國王說預言。」這代表我們要去告訴世界：如果不離開壞事、不回到上帝面前，會有審判臨到。這份責任讓約翰感到心裡沉甸甸的，這就是「苦」的味道。",
