        "rawText": "我又觀看，見羔羊站在錫安山，同他又有十四萬四千人，都有他的名和他父的名寫在額上。我聽見從天上有聲音，像眾水的聲音和大雷的聲音，並且我所聽見的好像彈琴的所彈的琴聲。他們在寶座前，並在四活物和眾長老前唱歌，彷彿是新歌；除了從地上買來的那十四萬四千人以外，沒有人能學這歌。…在他們口中察不出謊言來，他們是沒有瑕疵的。我又看見另一位天使飛在空中，有永遠的福音要傳給住在地上的人，就是各國、各族、各方、各民。\n我又觀看，見有一片白雲，雲上坐著一位好像人子，頭上戴著金冠冕，手裡拿著快鐮刀。又有一位天使從殿中出來，向那坐在雲上的大聲喊著說：「伸出你的鎌刀來收割；因為收割的時候已經到了，地上的莊稼已經熟透了。」那坐在雲上的，就把鐮刀扔在地上，地上的莊稼就被收割了。\n啟示錄 14章1-3, 5-6, 14-16節",
        "teacherScript": "『請大家注意看這個重點：【主題經文】。這段話告訴我們上帝對我們每個人的美好心意！』",
