        "rawText": "（啟示錄20-22章）\n背誦金句：「看哪，上帝的帳幕在人間。他要與人同住，他們要作他的子民，上帝要親自與他們同在，作他們的上帝。」（啟示錄21章3節下半節）\n信息經文：啟示錄20章8節至二十二章　主題經文：啟示錄21章1-7節\n我又看見一個新天新地；因為先前的天地已經過去了，海也不再有了。我又看見聖城新耶路撒冷由上帝那裡從天而降，預備好了，就如新婦妝飾整齊，等候丈夫。我聽見有大聲音從寶座出來說：「看哪，上帝的帳幕在人間。他要與人同住，他們要作他的子民，上帝要親自與他們同在，作他們的上帝。上帝要擦去他們一切的眼淚；不再有死亡，也不再有悲哀、哭號、疼痛，因為以前的事都過去了。坐寶座的說：「看哪！我將一切都更新了。」又說：「你要寫上；因為這些話是可信的，是真實的。」他又對我說：「都成了！我是阿拉法，我是俄梅戞；我是初，我是終。我要將生命泉的水白白賜給那口渴的人喝。得勝的，必承受這些為業；我要作他的上帝，他要作我的兒子。」",
