        "title": "✊ 心中的頑固與手心的緊閉",
        "timing": "⏱️ 建議停留：2-3 分鐘",
        "rawText": "摩西說了一句非常重要的話：「你若遇到貧窮的弟兄，不可心裡頑固，也不可手掌緊閉。」\n😟 緊閉的手\n「這是我的餅乾！」「萬一給了你，我不夠用怎麼辦？」\n因為害怕失去而緊握\n無法給予別人幫助\n也無法接住上帝的祝福\n🙌 敞開的手\n當你看見別人需要，鬆開那緊握的拳頭！\n勇敢地分享你所有的\n成為別人的幫助\n接住上帝更大的祝福\n上帝挑戰我們：你能否在看見別人需要時，鬆開那緊握的拳頭？👐",
        "teacherScript": "『請大家注意看這個重點：【✊ 心中的頑固與手心的緊閉】。這段話告訴我們上帝對我們每個人的美好心意！』",
