        "timing": "⏱️ 建議停留：8-10 分鐘",
        "rawText": "選擇題：一起動動腦！\n1\n上帝說祂會給我們什麼來指引我們？\nA. 一個指路標　B. 一位先知　C. 一台導航機\n2\n我們要如何知道這是上帝的話？\nA. 順服聖經教導　B. 看誰聲音大　C. 看誰人多\n3\n遇到不知道怎麼辦的事情，我們可以做什麼？\nA. 哭泣　B. 跟隨朋友　C. 禱告求問上帝\n4\n假先知說的話會怎麼樣？\nA. 都會實現　B. 都不會實現　C. 偶爾實現\n5\n我們要聽從上帝的話是因為什麼？\nA. 因為祂愛我們　B. 因為祂會懲罰　C. 因為大家都聽",
        "teacherScript": "『今天的故事大家有沒有聽懂呢？現在是搶答大考驗時間！請看投影片上的題目，知道答案的小朋友請快速舉手！』",
        "studentPrompt": "低年級小朋友選出正確選項，高年級同學思考為什麼會這樣！"
