        "rawText": "開放式問題──分享你的想法！\n🎧 問題一\n你覺得在現在的生活中，什麼聲音最容易讓你分心，而忘記上帝的話？\n📱 問題二\n面對現今網路社群上各種不同的流行觀點，我們該如何練習運用上帝的話語作為「濾網」，來分辨什麼是真實的、什麼是虛假的？\n🔍 問題三\n✝️ 問題四\n你認為認識耶穌基督，\n對於我們分辨真理有什麼重要的幫助？\n🌟 問題五\n請分享一件你曾經因為聽從上帝的教導\n而感到平安或順利的經歷。\n「測試先知」的標準是看\n他的預言有沒有應驗，這給我們什麼啟示？",
        "teacherScript": "『今天的故事大家有沒有聽懂呢？現在是搶答大考驗時間！請看投影片上的題目，知道答案的小朋友請快速舉手！』",
        "studentPrompt": "低年級小朋友選出正確選項，高年級同學思考為什麼會這樣！"
