        "rawText": "親愛的天父:\n感謝你透過聖經賜給我們智慧，讓我們能在這充滿嘈雜的世界中，聽見你真實的聲音。求你賜給我們一顆敏銳與謙卑的心，學習分辨真假，不被謊言迷惑。特別是在我們遇到選擇的時候，幫助我們勇敢選擇順服你的教導，走在你為我們預備的光明道路上。求你讓這堂課的內容，深植在我們的心中，成為我們隨時的幫助與力量。奉耶穌基督的名禱告，阿們。🙏\n小朋友，我們擁有比雲柱火柱更清晰的指南──上帝的話語！這是祂給我們最珍貴的禮物，讓我們帶著這份禮物，勇敢邁向每一天的挑戰！🌈",
        "teacherScript": "『讓我們安靜我們的心，雙手合十、閉上眼睛。老師唸一句，大家跟著唸一句，我們一起把今天的話語放在心裡！』",
        "studentPrompt": "在心裡向耶穌說一聲：主耶穌，我愛你！"
