        "rawText": "四十年的旅程\n從埃及的奴隸到曠野的漂流，以色列人走過了四十年漫長艱辛的路，經歷了無數次神蹟。如今，他們終於站在約旦河東，隔著河就能看到上帝應許的土地！\n摩西最後的叮嚀\n摩西雖然已經一百二十歲了，但他看著眼前這些如孩子般的百姓，心中充滿了不捨與叮嚀。他召集所有百姓，進行最後一次嚴肅的訓勉：\n「你們要把我今日警戒你們的話，放在心上；要吩咐你們的子孫謹守遵行，因為這不是空話，是你們的生命！」\n他明白，沒有上帝的話語，以色列人只不過是曠野中的流浪者；只有守住上帝的約，他們才能在新土地上生根發芽。",
