        "rawText": "天窗敞開的應許 🪟✨\n「你們試試看！把當納的十分之一全部送入倉庫，使我家有糧。試試我是否會為你們敞開天上的窗戶，傾福與你們，直到無處可容！」\n不是交易\n這不是一場交易，而是一個愛的邀約！\n慈愛天父\n上帝想要證明，祂是那位負責供應一切的慈愛天父！\n順服與信心\n祂不是需要我們的錢財，祂要的是我們的順服與信心！",
        "teacherScript": "『孩子們，讓我們把時光倒流！看著這幅圖畫，主角正在面臨前所未有的考驗……想像如果是你，你會怎麼辦？』",
