        "rawText": "聖經故事 第一幕\n無處可去的旅程\n在那個遙遠的兩千多年前，羅馬皇帝該撒亞古士督下了一道嚴厲的命令，要求普天下的人都要回到自己的家鄉報名上冊。這對約瑟來說是一個巨大的挑戰，因為他的妻子馬利亞此時已經身孕已經重了，孩子隨時都可能出生。\n他們沿著蜿蜒的山路，從拿撒勒辛苦地走向大衛的城伯利恆。當他們終於抵達伯利恆時，這座原本安靜的小城已經擠滿了從各地趕回的人。大街小巷人聲鼎沸，所有的客店門口都掛著「客滿」的牌子。\n約瑟敲了一扇又一扇的門：「請問有地方可以讓我的妻子休息嗎？她快要生產了。」但得到的答案都是冷漠的拒絕。最後，一位店主說：「後院的馬廄還有一點空間，如果你們不介意和牲畜待在一起……」",
