        "timing": "⏱️ 建議停留：8-10 分鐘",
        "rawText": "冰棒棍立體馬槽 🏠\n用冰棒棍做一個可以掛在聖誕樹上的立體馬槽吊飾，帶回家紀念！\n🛒 所需材料\n冰棒棍\n乾草（或牛皮紙條）\n耶穌嬰孩小卡\n保麗龍膠\n掛繩\n📋 製作步驟\n使用三根冰棒棍黏貼成三角形，作為馬廄的屋頂。\n在三角形下方用四根冰棒棍組成長方形的地板與牆壁。\n在馬廄中央塗上大量膠水，舖上碎乾草。\n將耶穌嬰孩的小卡貼在乾草中央。\n在頂部繫上掛繩，成為聖誕樹的紀念吊飾！🎄",
        "teacherScript": "『大家準備好了嗎？我們現在要進行超好玩的破冰遊戲【✂️ 手工活動二】！遊戲的規則非常簡單，請大家豎起耳朵聽清楚囉！』",
        "studentPrompt": "在遊戲中請注意安全，輸贏不重要，最重要的是彼此相愛互相加油！"
