        "rawText": "低年級（1–3年級）\n選擇題時間！你答對了嗎？🌟\n1\n耶穌降生後被放在哪裡？\n（A）柔軟的大床　（B）搖籃　（C）給動物吃草的馬槽\n2\n誰最先在野地收到天使的消息？\n（A）國王　（B）牧羊人　（C）商人\n3\n天使說這信息是關乎誰的？\n（A）只有大人　（B）只有小孩　（C）關乎萬民\n4\n天使歌頌「在至高之處榮耀歸與」誰？\n（A）上帝　（B）總統　（C）校長\n5\n牧羊人看到耶穌後做了什麼？\n（A）睡覺　（B）趕快跑去傳好消息　（C）什麼都不說",
        "teacherScript": "『今天的故事大家有沒有聽懂呢？現在是搶答大考驗時間！請看投影片上的題目，知道答案的小朋友請快速舉手！』",
        "studentPrompt": "低年級小朋友選出正確選項，高年級同學思考為什麼會這樣！"
