        "rawText": "高年級（4–6年級）\n思考與分享時間 🤔\n1\n謙卑的啟示\n為什麼耶穌會降生在卑微的馬廄？這對你有什麼啟發？\n2\n上帝的選擇\n當時的社會地位中，牧羊人是被看輕的。上帝為何先向他們顯現？\n3\n萬民的意思\n「大喜的信息是關乎萬民的」，你認為「萬民」包含哪些人？\n4\n馬利亞的心情\n當馬利亞「反覆思想」這些事時，你覺得她的心情可能是什麼？\n5\n我來分享！\n如果今天要你向同學分享「耶穌是救主」，你會怎麼介紹？",
        "teacherScript": "『今天的故事大家有沒有聽懂呢？現在是搶答大考驗時間！請看投影片上的題目，知道答案的小朋友請快速舉手！』",
        "studentPrompt": "低年級小朋友選出正確選項，高年級同學思考為什麼會這樣！"
