        "rawText": "親愛的天父:\n我們感謝你！謝謝你在那個寂靜的夜晚，將主耶穌當作最寶貴的禮物賜給我們。謝謝你讓我們看見，耶穌願意降生在卑微的馬槽，是因為祂深深地愛著我們每一個人。求上帝幫助我們，像牧羊人一樣有單純渴慕的心，隨時準備好分享你的愛與平安。願你的話語在我們心中發光，指引我們的腳步。\n奉主耶穌基督聖名禱告，阿們！🙏\n🎄 聖誕快樂！願耶穌的愛與平安充滿你的心！🎄",
